                   (size_t)calculated_size, 16 * 6 * alloc_size);
            // In the real vulnerability, subsequent slice decoding
            // writes 16 * 6 * alloc_size bytes into this small buffer,
            // causing a heap buffer overflow.
            free(ptr);
        }
    }
}

